from collections import deque
R,C=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  col=grid[r][c]
  if col in (6,9) or (r,c) in seen: continue
  q=[(r,c)]; seen.add((r,c)); cells=[]
  for x,y in q:
   cells.append((x,y))
   for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
    if 0<=a<R and 0<=b<C and grid[a][b]==col and (a,b) not in seen:
     seen.add((a,b));q.append((a,b))
  comps.append((col,cells))
[(col,len(cells),(min(r for r,c in cells),min(c for r,c in cells),max(r for r,c in cells),max(c for r,c in cells)), sorted(cells)) for col,cells in comps]
